// src/Createemp.tsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import type { IPerson } from "./models/IPerson"; // type-only import
import { addEmployee } from "./services/employeeService";

const Createemp: React.FC = () => {
  // State holds an employee object without the id (since it's generated by backend)
  const [employee, setEmployee] = useState<Omit<IPerson, "id">>({
    name: "",
    email: "",
    department: "",
  });

  const navigate = useNavigate();

  const handleChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ): void => {
    const { name, value } = event.target;
    setEmployee((values) => ({ ...values, [name]: value }));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    try {
      const newEmployee = await addEmployee(employee);
      console.log("Employee created:", newEmployee);
      navigate("/Listemployee"); // redirect to list after creation
    } catch (error) {
      console.error("Error creating employee:", error);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>Name:</label>
      <input
        type="text"
        name="name"
        value={employee.name}
        onChange={handleChange}
        required
      />
      <br />

      <label>Email:</label>
      <input
        type="email"
        name="email"
        value={employee.email}
        onChange={handleChange}
        required
      />
      <br />

      <label>Department:</label>
      <input
        type="text"
        name="department"
        value={employee.department}
        onChange={handleChange}
        required
      />
      <br />

      <input type="submit" value="Create Employee" />
    </form>
  );
};

export default Createemp;
